        e.preventDefault();
        setView('accessibility');
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        setView('retrospective');
      } else if (e.key === 'c' || e.key === 'C') {
        e.preventDefault();
        setIsCustomizationModalOpen(true);
      } else if (e.key === 'g' || e.key === 'G') {
